package com.ruoyi.medical.persistence;

import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.util.*;
import javax.net.ssl.SSLContext;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;

/** Explicit opt-in deployment. No profile, TLS identity, storage, authority or approval defaults.
 * Enabling this without genuine dependent services/configuration fails startup. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.professional-runtime.task-enabled",havingValue="true",matchIfMissing=false)
public class TaskProfessionalConfiguration {
    @Bean TaskProfessionalRuntimeService.Deployment taskProfessionalDeployment(
            @Value("${medical.professional-runtime.deployment-file}") Path file,
            @Value("${medical.professional-runtime.deployment-owner}") String owner,
            @Value("${medical.professional-runtime.deployment-sha256}") String expected,
            @Value("${medical.professional-runtime.maximum-deployment-bytes}") int maximum)throws Exception {
        return readDeployment(file,owner,expected,maximum);
    }
    static TaskProfessionalRuntimeService.Deployment readDeployment(Path file,String owner,String expected,int maximum)throws Exception {
        if(file==null||!file.isAbsolute()||!file.normalize().equals(file)||owner==null||owner.isBlank()||maximum<1||maximum>2097152||!file.toRealPath().equals(file))throw new IllegalArgumentException("PINNED_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        var principal=file.getFileSystem().getUserPrincipalLookupService().lookupPrincipalByName(owner);
        var before=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);
        if(!before.isRegularFile()||before.size()<1||before.size()>maximum||!Files.getOwner(file,LinkOption.NOFOLLOW_LINKS).equals(principal))throw new IllegalArgumentException("OWNED_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        var permissions=Files.getPosixFilePermissions(file,LinkOption.NOFOLLOW_LINKS);if(!Set.of(PosixFilePermissions.fromString("r--------"),PosixFilePermissions.fromString("rw-------")).contains(permissions))throw new IllegalArgumentException("PRIVATE_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        byte[] bytes;try(var input=Files.newInputStream(file,LinkOption.NOFOLLOW_LINKS)){bytes=input.readNBytes(maximum+1);}var after=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);
        if(bytes.length!=before.size()||bytes.length>maximum||!Objects.equals(before.fileKey(),after.fileKey())||!before.lastModifiedTime().equals(after.lastModifiedTime())||before.size()!=after.size())throw new IllegalArgumentException("PROFESSIONAL_DEPLOYMENT_CHANGED");
        var json=com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
        return new TaskProfessionalRuntimeService.Deployment(json.readTree(bytes),expected);
    }
    @Bean TaskProfessionalSchema taskProfessionalSchema()throws Exception{return new TaskProfessionalSchema();}
    @Bean(name="taskProfessionalObjectTransport") RuntimeObjectTransport taskProfessionalObjectTransport(SourceUploadTransport objects,TaskProfessionalRuntimeService.Deployment deployment,@Value("${medical.professional-runtime.object-directory}")Path directory)throws Exception{return new RuntimeObjectTransport(objects,directory,deployment.maximumBytes());}
    @Bean(name="taskProfessionalLineageLimits") DependencyLineage.Limits taskProfessionalLineageLimits(@Value("${medical.professional-runtime.maximum-lineage-versions}")int versions,@Value("${medical.professional-runtime.maximum-lineage-relations}")int relations){return new DependencyLineage.Limits(versions,relations);}
    @Bean TaskProfessionalRuntimeService taskProfessionalRuntimeService(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskNodeInputAuthority inputs,TaskProfessionalRuntimeService.Deployment deployment,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identities,TaskNodeProducerAuthority producers){return new TaskProfessionalRuntimeService(data,json,inputs,deployment,identities,producers);}
    @Bean TaskProfessionalPromptCompiler taskProfessionalPromptCompiler(@Qualifier("masterDataSource")DataSource data,FormalCapabilityIdentityAuthority roles,TaskNodeInputAuthority inputs,PermissionSchema json,TaskProfessionalPredecessorEvidence predecessors)throws Exception{return new TaskProfessionalPromptCompiler(data,roles,inputs,json,predecessors);}
    @Bean TaskProfessionalPredecessorEvidence taskProfessionalPredecessorEvidence(@Qualifier("masterDataSource")DataSource data,TaskNodeInputAuthority inputs,TaskResearchCompletionAuthority completions,TaskProfessionalObjectRegistration objects,TaskProfessionalContentAuthority contents,TaskNodeProducerAuthority producers,TaskProfessionalSupervisor supervisor,TaskProfessionalRuntimeService.Deployment deployment,SourceUploadTransport transport,SourceReadAuthority sources,TaskProfessionalSchema schema,PermissionSchema json){return new TaskProfessionalPredecessorEvidence(data,inputs,completions,objects,contents,producers,supervisor,deployment,transport,sources,schema,json);}
    @Bean TaskProfessionalHostAccess taskProfessionalHostAccess(FormalWorkerAccess workers,TaskNodeInputAuthority inputs,TaskNodeProducerAuthority producers,TaskProfessionalRuntimeService runtime,SourceUploadTransport transport,TaskProfessionalRuntimeService.Deployment deployment){return new TaskProfessionalHostAccess(workers,inputs,producers,runtime,transport,deployment);}
    @Bean TaskProfessionalObjectLedger taskProfessionalObjectLedger(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskProfessionalSchema schema){return new TaskProfessionalObjectLedger(data,json,schema);}
    @Bean TaskProfessionalContentAuthority taskProfessionalContentAuthority(ArtifactRegistryMapper artifacts,VersionResourceMapper owners,DependencyManifestSchema manifests,DependencyLineage lineage,@Qualifier("taskProfessionalLineageLimits")DependencyLineage.Limits limits){return new TaskProfessionalContentAuthority(artifacts,owners,manifests,lineage,limits);}
    @Bean TaskProfessionalObjectGovernance taskProfessionalObjectGovernance(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskProfessionalSchema schema,DependencyLineage lineage,@Qualifier("taskProfessionalLineageLimits")DependencyLineage.Limits limits){return new TaskProfessionalObjectGovernance(data,json,schema,lineage,limits);}
    @Bean TaskProfessionalObjectRegistration taskProfessionalObjectRegistration(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskProfessionalSchema schema,TaskProfessionalObjectLedger ledger,TaskProfessionalObjectGovernance governance,TaskProfessionalContentAuthority content,DependencyManifestSchema manifests,DependencyLineage lineage,@Qualifier("taskProfessionalLineageLimits")DependencyLineage.Limits limits){return new TaskProfessionalObjectRegistration(data,json,schema,ledger,governance,content,manifests,lineage,limits);}
    @Bean TaskProfessionalSupervisor taskProfessionalSupervisor(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,@Qualifier("taskProfessionalSupervisorTrust")ServiceCertificateIdentity.TrustSource trust,@Qualifier("taskProfessionalSupervisorTls")com.ruoyi.medical.identity.ServiceClientTlsStore.ContextSource tls){return new TaskProfessionalSupervisor(data,json,new ServiceCertificateIdentity(trust),trust,tls);}
    @Bean TaskProfessionalSupervisorGate taskProfessionalSupervisorGate(@Qualifier("masterDataSource")DataSource data,TenantTransaction transactions,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services,TaskProfessionalRuntimeService.Deployment deployment,PermissionMapper permissions,PermissionAuthority grants,PlatformMemberIdentityStatus identities,PermissionSchema json,@org.springframework.beans.factory.annotation.Qualifier("taskNodeProducerSchema") TaskNodeProducerSchema producerSchema,TaskDelegationSchema delegationSchema,SourceUploadTransport objects,TaskProfessionalSchema schema){return new TaskProfessionalSupervisorGate(data,transactions,services,deployment,permissions,grants,identities,json,producerSchema,delegationSchema,objects,schema);}
    @Bean TaskResearchRetrievalAuthority taskResearchRetrievalAuthority(RetrievalService service,RetrievalMapper mapper,RetrievalSchema schema,PermissionSchema json){return new TaskResearchRetrievalAuthority(service,mapper,schema,json);}
    @Bean TaskResearchExecutionService taskResearchExecutionService(PermissionSchema json,TaskProfessionalSchema schema,TaskResearchSourceReader sources,TaskResearchRetrievalAuthority retrievals){return new TaskResearchExecutionService(json,schema,sources,retrievals);}
    @Bean TaskResearchRuleInputs taskResearchRuleInputs(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,ProjectSchema projects,TemplateApplicabilitySchema rules,TemplateMapper rows,DependencyLineage lineage,VersionResourceAuthority versions,SourceReadAuthority sources,SourceReadMapper sourceRows,ArtifactRegistryMapper artifacts,EvaluationReferences profiles,EvaluationDependencyPolicy limits){limits.requireConfigured();return new TaskResearchRuleInputs(data,json,projects,rules,rows,lineage,versions,sources,sourceRows,artifacts,profiles,limits);}
    @Bean TaskResearchWaitingService taskResearchWaitingService(EnterpriseAccess access,@Qualifier("masterDataSource")DataSource data,ResourceReadAuthority resources,PermissionSchema json)throws Exception{return new TaskResearchWaitingService(access,data,resources,json);}
    @Bean TaskResearchCompletionEvaluation taskResearchCompletionEvaluation(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,RuleExpression engine,TaskResearchRuleInputs rules,TaskResearchWaitingService waiting){return new TaskResearchCompletionEvaluation(data,json,engine,rules,waiting);}
    @Bean TaskProfessionalHostOrchestrator taskProfessionalHostOrchestrator(TaskProfessionalHostAccess hosts,TaskProfessionalRuntimeService runtime,TaskProfessionalPromptCompiler prompts,TaskInvocationPackages packages,TaskNodeProducerAuthority producers,TaskProfessionalObjectLedger ledger,@Qualifier("taskProfessionalObjectTransport")RuntimeObjectTransport objects,TaskProfessionalObjectRegistration registration,TaskProfessionalSupervisor supervisor,TaskRuntimeJournal journal,PermissionSchema json){return new TaskProfessionalHostOrchestrator(hosts,runtime,prompts,packages,producers,ledger,objects,registration,supervisor,journal,json);}
    @Bean TaskResearchFinishOrchestrator taskResearchFinishOrchestrator(TaskProfessionalHostAccess hosts,ProfessionalRuntimeObservations observations,TaskProfessionalSupervisor supervisor,TaskInvocationService invocations,TaskResearchExecutionService outputs,TaskResearchCompletionEvaluation evaluator,TaskNodeProducerAuthority producers,TaskProfessionalObjectLedger ledger,@Qualifier("taskProfessionalObjectTransport")RuntimeObjectTransport transport,TaskProfessionalObjectRegistration registration,PermissionSchema json){return new TaskResearchFinishOrchestrator(hosts,observations,supervisor,invocations,outputs,evaluator,producers,ledger,transport,registration,json);}
    @Bean TaskHostControlBootstrap taskHostControlBootstrap(@Qualifier("masterDataSource")DataSource data,FormalTaskNodeAuthority nodes,RunTokenAuthority tokens,TaskProfessionalHostAccess hosts,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services,TaskProfessionalRuntimeService.Deployment deployment,PermissionSchema json,RunTokenAuthoritySchema schema,TaskRuntimeJournal journal,TaskRunLaunchRecoveryAuthority recoveries,TaskRunWorkflowLedger launches){return new TaskHostControlBootstrap(data,nodes,tokens,hosts,services,deployment,json,schema,journal,recoveries,launches);}
    @Bean TaskResearchToolReceipts taskResearchToolReceipts(@Qualifier("masterDataSource")DataSource data,TaskProfessionalSupervisor supervisor,FormalRuntimeCapabilityIdentityAuthority capabilities,TaskResearchSourceReader sources,TaskResearchRetrievalAuthority retrievals,PermissionSchema json,TaskRegisteredToolReceipts registered)throws Exception{return new TaskResearchToolReceipts(data,supervisor,capabilities,sources,retrievals,json,registered);}
    @Bean TaskResearchToolBridge taskResearchToolBridge(@Qualifier("masterDataSource")DataSource data,TaskProfessionalHostAccess hosts,TaskProfessionalSupervisor supervisor,TaskInvocationService invocations,TaskResearchToolAccess tools,RunTokenAuthority tokens,TaskResearchToolReceipts receipts,PermissionSchema json,RunTokenAuthoritySchema schema)throws Exception{return new TaskResearchToolBridge(data,hosts,supervisor,invocations,tools,tokens,receipts,json,schema);}
    @Bean TaskRegisteredToolAuthority taskRegisteredToolAuthority(@Qualifier("masterDataSource")DataSource data,TaskProfessionalSupervisor supervisor,FormalRuntimeCapabilityIdentityAuthority capabilities,FormalCapabilityIdentityAuthority roles,ResourceReadAuthority resources,PermissionSchema json)throws Exception{return new TaskRegisteredToolAuthority(data,supervisor,capabilities,roles,resources,json);}
    @Bean TaskRegisteredToolWaitingService taskRegisteredToolWaitingService(@Qualifier("masterDataSource")DataSource data,TaskResearchRuleInputs rules,PermissionSchema json)throws Exception{return new TaskRegisteredToolWaitingService(data,rules,json);}
    @Bean TaskRegisteredToolReceipts taskRegisteredToolReceipts(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskRegisteredToolAuthority authority,TaskProfessionalPredecessorEvidence predecessors,TaskInvocationPackages packages,TaskRegisteredToolWaitingService waiting,RunTokenAuthoritySchema actions,FormalRuntimeCapabilityIdentityAuthority capabilities,FormalCapabilityIdentityAuthority roles,TaskProfessionalObjectRegistration objects,TaskProfessionalSupervisor supervisor,TaskProfessionalRuntimeService.Deployment deployment)throws Exception{return new TaskRegisteredToolReceipts(data,json,authority,predecessors,packages,waiting,actions,capabilities,roles,objects,supervisor,deployment);}
    @Bean TaskRegisteredToolBridge taskRegisteredToolBridge(TaskProfessionalHostAccess hosts,TaskProfessionalSupervisor supervisor,TaskInvocationService invocations,TaskRegisteredToolAuthority authority,TaskRegisteredToolReceipts receipts,TaskProfessionalPredecessorEvidence predecessors,TaskInvocationPackages packages,TaskRegisteredToolWaitingService waiting,PermissionSchema json,org.springframework.beans.factory.ObjectProvider<TaskRegisteredToolWaitingGate> gate)throws Exception{return new TaskRegisteredToolBridge(hosts,supervisor,invocations,authority,receipts,predecessors,packages,waiting,json,gate.getIfAvailable());}
}
